  --gold-deep: #9c7d42;
  --line: rgba(215, 193, 139, 0.2);
  --line-strong: rgba(222, 200, 148, 0.4);
  --panel: rgba(18, 23, 17, 0.92);
  --panel-deep: rgba(12, 16, 12, 0.96);
