  justify-content: center;
  border: 1px solid rgba(215, 193, 139, 0.2);
  background: radial-gradient(circle at 50% 40%, rgba(255, 255, 255, 0.06), rgba(10, 13, 9, 0.6));
  color: var(--faction);
}
.unit-banner-icon svg { width: 31px; height: 31px; }
.unit-banner-copy { flex: 1; min-width: 0; }
.unit-banner-copy span, .group-header span, .sector-head span:not(.sector-flag):not(.capital-mark), .war-faction span:not(.war-flag) { font-size: 7px; letter-spacing: 0.16em; color: var(--ink-faint); }
.unit-banner-copy h3, .group-header h3, .sector-head h3, .war-faction h3 {
  margin: 3px 0 0;
  font-family: var(--serif);
  font-size: 18px;
  line-height: 1.1;
  font-weight: 400;
  color: #e8dfc5;
}
.unit-hp { font-family: var(--serif); font-size: 22px; color: #ddcfaa; white-space: nowrap; }
.unit-hp small { font-size: 10px; color: var(--ink-faint); }

.hp-track { height: 4px; background: rgba(7, 9, 6, 0.7); border: 1px solid rgba(215, 193, 139, 0.1); overflow: hidden; }
.hp-track i { display: block; height: 100%; background: var(--hp, var(--gold)); box-shadow: 0 0 8px rgba(220, 195, 130, 0.25); transition: width 0.25s ease; }
.hp-large { height: 6px; }

.unit-stat-grid, .sector-stats, .war-stats, .gameover-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1px;
  background: rgba(215, 193, 139, 0.09);
  border: 1px solid rgba(215, 193, 139, 0.09);
}
.unit-stat-grid div, .sector-stats div, .war-stats div, .gameover-stats div {
  padding: 8px 6px;
  background: rgba(11, 15, 10, 0.66);
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.unit-stat-grid span, .sector-stats span, .war-stats span, .gameover-stats span { font-size: 6.5px; letter-spacing: 0.13em; color: var(--ink-faint); }
.unit-stat-grid b, .sector-stats b, .war-stats b, .gameover-stats b { font-family: var(--serif); font-size: 13px; color: #dacdac; font-weight: 400; }

.unit-status-row { display: flex; gap: 5px; flex-wrap: wrap; }
.status-pill { padding: 3px 6px; border: 1px solid rgba(215, 193, 139, 0.13); font-size: 7px; letter-spacing: 0.12em; color: #928971; }
.status-pill.good { color: #b9c99a; border-color: rgba(152, 176, 124, 0.3); }
.order-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 5px; }
.order-grid button {
  min-height: 31px;
  padding: 6px 7px;
  border: 1px solid rgba(215, 193, 139, 0.17);
  background: rgba(27, 34, 24, 0.7);
  color: #c8bc9e;
  font-size: 8px;
  letter-spacing: 0.09em;
  cursor: pointer;
  transition: border-color 0.15s, background 0.15s;
}
.order-grid button:hover { border-color: rgba(232, 206, 147, 0.5); background: rgba(40, 50, 34, 0.8); }
.order-grid button.accent { border-color: rgba(222, 197, 135, 0.5); color: var(--gold-bright); }
.order-grid button kbd { margin-left: 3px; height: 14px; min-width: 15px; font-size: 7px; }
.unit-flavour { margin: 0; font-family: var(--serif); font-size: 10px; line-height: 1.45; color: #9e947b; }

.group-header { display: flex; align-items: flex-end; justify-content: space-between; gap: 10px; }
.composition { display: flex; flex-wrap: wrap; gap: 5px; }
.composition span { padding: 4px 6px; border: 1px solid rgba(215, 193, 139, 0.12); font-size: 8px; color: var(--ink-faint); }
.composition b { color: #d8cba9; font-weight: 500; }

.sector-head { display: flex; align-items: center; gap: 10px; padding-bottom: 10px; border-bottom: 1px solid rgba(215, 193, 139, 0.14); }
.sector-flag { width: 40px; flex: 0 0 40px; }
.sector-flag svg { width: 100%; display: block; border: 1px solid rgba(239, 229, 196, 0.24); }
.sector-head div { flex: 1; min-width: 0; }
.sector-head h3 { font-size: 20px; }
.capital-mark { padding: 3px 5px; border: 1px solid rgba(226, 201, 141, 0.3); color: var(--gold); font-size: 6px; letter-spacing: 0.13em; }
.sector-owner-line { display: flex; align-items: center; justify-content: space-between; font-size: 7px; letter-spacing: 0.1em; color: var(--ink-faint); }
.sector-owner-line b { font-family: var(--serif); font-size: 12px; font-weight: 400; }
.capture-line { display: flex; flex-direction: column; gap: 5px; }
.capture-copy { display: flex; justify-content: space-between; font-size: 7px; letter-spacing: 0.12em; color: var(--ink-faint); }
.capture-copy b { color: #d5c8a7; font-weight: 500; }
.sector-stats { grid-template-columns: repeat(3, 1fr); }

.war-faction { display: flex; align-items: center; gap: 11px; padding-bottom: 11px; border-bottom: 1px solid rgba(215, 193, 139, 0.14); }
.war-flag { width: 48px; flex: 0 0 48px; }
.war-flag svg { width: 100%; display: block; border: 1px solid rgba(239, 229, 196, 0.24); box-shadow: 0 3px 10px rgba(0, 0, 0, 0.3); }
.war-faction h3 { font-size: 18px; }
.doctrine-block { padding: 9px 10px; border-left: 2px solid var(--faction); background: rgba(30, 37, 27, 0.55); }
.doctrine-block span { display: block; font-size: 6.5px; letter-spacing: 0.17em; color: var(--gold-deep); }
.doctrine-block b { display: block; margin: 2px 0 4px; font-family: var(--serif); font-size: 15px; font-weight: 400; color: #e2d7b8; }
.doctrine-block p { margin: 0; font-size: 8px; line-height: 1.4; color: #a79b80; }
.war-stats { grid-template-columns: repeat(3, 1fr); }
.war-objective { display: flex; flex-direction: column; gap: 5px; }
.war-objective > div:first-child { display: flex; justify-content: space-between; align-items: center; }
.war-objective span { font-size: 6.5px; letter-spacing: 0.15em; color: var(--ink-faint); }
.war-objective b { font-family: var(--serif); font-size: 11px; color: #d6c8a6; font-weight: 400; }
.war-log > span { font-size: 6.5px; letter-spacing: 0.17em; color: var(--gold-deep); }
.war-log ul { list-style: none; margin: 5px 0 0; padding: 0; display: flex; flex-direction: column; gap: 5px; }
.war-log li { padding-left: 8px; border-left: 1px solid rgba(215, 193, 139, 0.18); font-family: var(--serif); font-size: 9.5px; line-height: 1.3; color: #a9a087; }
.war-note { margin: 0; padding-top: 8px; border-top: 1px solid rgba(215, 193, 139, 0.1); font-size: 8px; line-height: 1.5; letter-spacing: 0.04em; color: #857d68; }

/* Minimap */
#minimap-panel {
  position: absolute;
  right: 16px;
  bottom: 174px;
  width: 230px;
  pointer-events: auto;
}
#minimap { width: 100%; height: 105px; display: block; cursor: crosshair; }
.minimap-footer {
  display: flex;
  justify-content: space-between;
  padding: 5px 8px 6px;
  font-size: 6px;
  letter-spacing: 0.1em;
  color: #7d7561;
  background: rgba(12, 16, 11, 0.8);
  border-top: 1px solid rgba(215, 193, 139, 0.1);
}

/* Recruitment */
#recruit-dock {
  position: absolute;
  left: 50%;
  bottom: 16px;
  width: min(690px, calc(100vw - 430px));
  transform: translateX(-50%);
  pointer-events: auto;
}
.recruit-head {
  height: 34px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 0 10px;
  border-bottom: 1px solid rgba(215, 193, 139, 0.12);
  background: rgba(27, 34, 24, 0.52);
}
.recruit-head > div:first-child { display: flex; align-items: center; gap: 10px; }
.recruit-head .panel-tag { white-space: nowrap; }
#deploy-name { font-size: 8px; letter-spacing: 0.11em; color: #d1c29e; font-weight: 500; }
#queue-note { font-size: 6.5px; letter-spacing: 0.12em; color: #7d7561; white-space: nowrap; }
.recruit-cards { display: flex; gap: 4px; padding: 5px; }
.unit-card {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 4px;
  padding: 6px 7px 5px;
  background: linear-gradient(180deg, rgba(33, 41, 29, 0.78), rgba(16, 21, 15, 0.82));
  border: 1px solid rgba(215, 193, 139, 0.13);
  text-align: left;
  cursor: pointer;
  transition: border-color 0.15s, background 0.15s, transform 0.15s;
}
.unit-card:hover:not(.disabled) { border-color: rgba(230, 204, 143, 0.48); background: linear-gradient(180deg, rgba(46, 57, 39, 0.9), rgba(23, 29, 20, 0.9)); transform: translateY(-1px); }
.unit-card.disabled { opacity: 0.37; cursor: not-allowed; }
.unit-card-icon { height: 26px; color: var(--faction); display: flex; align-items: center; }
.unit-card-icon svg { width: 27px; height: 27px; }
.unit-card-copy { display: flex; flex-direction: column; gap: 1px; min-width: 0; }
.unit-card-copy b { font-family: var(--serif); font-size: 10px; font-weight: 400; color: #e1d7b9; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.unit-card-copy small { font-size: 6px; letter-spacing: 0.08em; text-transform: uppercase; color: #827a66; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.unit-card-foot { display: flex; justify-content: space-between; align-items: center; margin-top: 1px; }
.unit-cost { font-size: 8px; color: #c9bb98; }
.unit-cost i { color: var(--gold-deep); font-style: normal; font-size: 5.5px; letter-spacing: 0.08em; }
.unit-hotkey { min-width: 15px; padding: 1px 3px; border: 1px solid rgba(215, 193, 139, 0.2); font-size: 6px; color: #8c836d; text-align: center; }

/* Ability and hints */
#ability-dock {
  position: absolute;
  left: 16px;
  bottom: 47px;
  pointer-events: auto;
}
.ability-btn {
  width: 178px;
  min-height: 44px;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 6px 9px;
  border: 1px solid rgba(215, 193, 139, 0.24);
  background: linear-gradient(180deg, rgba(37, 45, 31, 0.95), rgba(16, 21, 15, 0.93));
  cursor: pointer;
  text-align: left;
  box-shadow: var(--shadow);
  position: relative;
  overflow: hidden;
  transition: border-color 0.15s, background 0.15s;
}
.ability-btn:hover:not(:disabled) { border-color: rgba(238, 211, 148, 0.6); background: linear-gradient(180deg, rgba(51, 61, 41, 0.96), rgba(20, 26, 18, 0.95)); }
.ability-btn.targeting { border-color: var(--gold-bright); box-shadow: 0 0 18px rgba(225, 191, 107, 0.2); }
.ability-btn.cooling { opacity: 0.58; }
.ability-btn:disabled { cursor: not-allowed; }
.ability-icon { width: 28px; height: 28px; display: flex; align-items: center; justify-content: center; border: 1px solid rgba(215, 193, 139, 0.24); color: var(--gold); font-size: 17px; }
.ability-copy { display: flex; flex-direction: column; gap: 2px; flex: 1; }
.ability-copy b { font-size: 9px; letter-spacing: 0.14em; color: #e3d4ad; font-weight: 500; }
.ability-copy small { font-size: 6px; letter-spacing: 0.13em; color: #817863; }
.ability-cd { font-size: 7px; letter-spacing: 0.08em; color: var(--gold); }

#hint-bar {
  position: absolute;
  left: 16px;
  bottom: 16px;
  display: flex;
  gap: 10px;
  align-items: center;
  color: #847c67;
  font-size: 6.5px;
  letter-spacing: 0.09em;
  white-space: nowrap;
  pointer-events: none;
}
#hint-bar span { display: flex; align-items: center; gap: 3px; }
#hint-bar .hint-gold { color: rgba(216, 189, 121, 0.68); letter-spacing: 0.12em; }
#hint-bar kbd { height: 14px; font-size: 6.5px; }

.armistice-banner {
  position: absolute;
  top: 76px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 7px 12px;
  border: 1px solid rgba(213, 188, 126, 0.28);
  background: rgba(18, 23, 16, 0.92);
  box-shadow: 0 8px 25px rgba(0, 0, 0, 0.35);
  color: #cfc19e;
  pointer-events: none;
  animation: armistice-pulse 2s ease-in-out infinite;
}
.armistice-kicker { color: var(--tone, var(--danger)); font-size: 7px; letter-spacing: 0.16em; }
#armistice-text { font-family: var(--serif); font-size: 11px; font-weight: 400; }
#armistice-count { font-family: var(--serif); font-size: 17px; color: var(--gold-bright); }
@keyframes armistice-pulse {
  0%, 100% { border-color: rgba(213, 188, 126, 0.22); }
  50% { border-color: rgba(213, 188, 126, 0.55); }
}

/* Toast */
.toast-stack {
  position: absolute;
  top: 82px;
  right: 338px;
  width: 270px;
  display: flex;
  flex-direction: column;
  gap: 5px;
  pointer-events: none;
}
.toast {
  padding: 8px 10px;
  border-left: 2px solid var(--tone);
  background: linear-gradient(90deg, rgba(20, 25, 18, 0.94), rgba(17, 21, 15, 0.72));
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.28);
  opacity: 0;
  transform: translateX(12px);
  transition: opacity 0.32s ease, transform 0.32s ease;
}
.toast.visible { opacity: 1; transform: translateX(0); }
.toast b { display: block; font-size: 8px; letter-spacing: 0.16em; color: var(--tone); font-weight: 500; }
.toast span { display: block; margin-top: 3px; font-family: var(--serif); font-size: 10px; line-height: 1.35; color: #c4b99d; }

/* Mobile bar (desktop hidden) */
.mobile-bar { display: none; }

/* Modal screens */
.modal-screen {
  z-index: 60;
  background: rgba(6, 9, 6, 0.72);
  backdrop-filter: blur(7px);
}

.manual-card {
  position: relative;
  width: min(940px, 92vw);
  max-height: 88vh;
  overflow-y: auto;
  padding: 36px 38px 32px;
  background:
    linear-gradient(180deg, rgba(26, 32, 23, 0.98), rgba(12, 16, 11, 0.99));
  border: 1px solid rgba(222, 201, 148, 0.28);
  box-shadow: 0 30px 90px rgba(0, 0, 0, 0.65);
  scrollbar-width: thin;
}
.manual-card::before {
  content: "";
  position: absolute;
  inset: 9px;
  border: 1px solid rgba(215, 193, 139, 0.09);
  pointer-events: none;
}
.modal-close {
  position: absolute;
  top: 12px;
  right: 15px;
  z-index: 2;
  width: 28px;
  height: 28px;
  border: 1px solid rgba(215, 193, 139, 0.2);
  background: transparent;
  color: #bdb197;
  font-size: 18px;
  cursor: pointer;
}
.modal-close:hover { border-color: rgba(230, 205, 143, 0.55); }
.manual-kicker, .pause-kicker, .gameover-kicker {
  font-size: 7px;
  letter-spacing: 0.24em;
  color: var(--gold-deep);
  text-transform: uppercase;
}
.manual-card h2, .pause-card h2, .gameover-card h2 {
  margin: 7px 0 18px;
  font-family: var(--serif);
  font-size: 34px;
  font-weight: 400;
  color: #e9dfc5;
}
.manual-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 22px 30px; margin-bottom: 24px; }
.manual-grid h3 { margin: 0 0 7px; font-family: var(--serif); font-size: 17px; font-weight: 400; color: #d9cba8; border-bottom: 1px solid rgba(215, 193, 139, 0.14); padding-bottom: 5px; }
.manual-grid p, .manual-grid li { font-family: var(--serif); font-size: 11px; line-height: 1.55; color: #a79c84; }
.manual-grid ul { margin: 6px 0 0; padding-left: 16px; }
.manual-grid li { margin-bottom: 3px; }
.manual-grid b { color: #d6c9a7; font-weight: 600; }

.pause-card, .gameover-card {
  width: min(400px, 88vw);
  padding: 34px 34px 28px;
  text-align: center;
  background: linear-gradient(180deg, rgba(27, 34, 24, 0.98), rgba(11, 15, 10, 0.99));
  border: 1px solid rgba(222, 201, 148, 0.25);
  box-shadow: 0 30px 90px rgba(0, 0, 0, 0.68);
}
.pause-card h2, .gameover-card h2 { margin-bottom: 8px; font-size: 38px; }
.pause-card p, .gameover-card p { margin: 0 0 20px; font-family: var(--serif); font-size: 12px; line-height: 1.5; color: #a79c84; }
.pause-card .btn, .gameover-card .btn { display: block; width: 100%; margin-top: 8px; }
.gameover-flag { margin: 0 auto 12px; width: 90px; }
.gameover-flag svg { width: 100%; display: block; border: 1px solid rgba(242, 230, 193, 0.3); box-shadow: 0 8px 24px rgba(0, 0, 0, 0.45); }
.gameover-stats { grid-template-columns: repeat(4, 1fr); margin: 18px 0 14px; }
.gameover-stats div { padding: 9px 5px; }

/* Responsive */
@media (max-width: 1180px) {
  .theatre { display: none; }
  #dossier { width: 282px; }
  .toast-stack { right: 314px; }
  #recruit-dock { width: calc(100vw - 368px); left: 198px; transform: none; }
  #minimap-panel { width: 206px; }
  #hint-bar .hint-gold { display: none; }
}

@media (max-width: 900px) {
  #dossier { display: none; }
  #minimap-panel { display: none; }
  #recruit-dock { left: 50%; width: calc(100vw - 220px); transform: translateX(-50%); }
  .toast-stack { right: 16px; }
  #faction-rail { width: 148px; }
  #hint-bar { display: none; }
  #ability-dock { bottom: 158px; }
}

@media (max-width: 760px) {
  #start-screen {
    padding: 18px 18px 14px;
    justify-content: flex-start;
    overflow-y: auto;
  }
  .start-screen::before { inset: 7px; }
  .start-screen::after { display: none; }
  .start-content { width: 100%; margin-top: 12px; padding-bottom: 20px; }
  .start-kicker { font-size: 7px; letter-spacing: 0.2em; gap: 8px; }
  .start-kicker span { width: 26px; }
  .start-content h1 { margin-top: 16px; font-size: clamp(42px, 14vw, 68px); }
  .start-subtitle { font-size: 11px; letter-spacing: 0.48em; text-indent: 0.48em; margin-top: 10px; }
  .start-lede { margin: 14px auto 17px; font-size: 12px; max-width: 320px; }
  .start-factions { grid-template-columns: 1fr 1fr; gap: 4px; }
  .start-faction { grid-template-columns: 32px 1fr 10px; min-height: 54px; padding: 7px; gap: 7px; }
  .start-faction-flag { width: 30px; }
  .start-faction-copy b { font-size: 10px; }
  .start-faction-copy small { font-size: 6.5px; }
  .start-faction:last-child { grid-column: span 2; }
  .start-doctrine { grid-template-columns: 36px 1fr; gap: 9px; padding: 8px 9px; margin: 7px 0 14px; }
  .doctrine-flag { width: 34px; }
  .doctrine-title { font-size: 13px; }
  .doctrine-copy p { font-size: 9px; }
  .doctrine-bonus { display: none; }
  .start-actions { gap: 6px; }
  .btn { min-width: 128px; padding: 11px 14px; font-size: 8.5px; }
  .start-note { font-size: 7px; line-height: 1.5; }
  .start-footer { display: none; }
  .manual-card { width: 94vw; padding: 25px 19px 22px; max-height: 90vh; }
  .manual-card h2 { font-size: 27px; }
  .manual-grid { grid-template-columns: 1fr; gap: 14px; }
  .manual-grid p, .manual-grid li { font-size: 10px; }

  #topbar {
    height: 52px;
    padding: 0 8px;
    gap: 6px;
  }
  .brand { min-width: 0; flex: 1; }
  .brand-kicker { font-size: 6px; letter-spacing: 0.2em; }
  .brand-title { font-size: 14px; letter-spacing: 0.08em; }
  .objective-strip { display: none; }
  .top-resources { gap: 7px; }
  .resource { min-width: 34px; }
  .resource-value { font-size: 12px; }
  .resource-label { display: none; }
  .icon-btn { width: 27px; height: 27px; font-size: 9px; }
  #sound-btn { display: none; }

  #faction-rail {
    top: 56px;
    left: 6px;
    right: 6px;
    width: auto;
    flex-direction: row;
    gap: 3px;
    overflow-x: auto;
    scrollbar-width: none;
  }
  #faction-rail::-webkit-scrollbar { display: none; }
  .faction-tab {
    flex: 1 0 0;
    min-width: 63px;
    height: 45px;
    grid-template-columns: 27px 1fr;
    gap: 4px;
    padding: 5px;
  }
  .tab-index, .tab-status { display: none; }
  .tab-flag { width: 27px; }
  .tab-copy { gap: 1px; }
  .tab-copy b { font-size: 8px; }
  .tab-copy small { font-size: 5.5px; letter-spacing: 0.04em; }
  .tab-copy small .tab-sectors { font-size: inherit; }

  #recruit-dock {
    left: 0;
    right: 0;
    bottom: calc(52px + env(safe-area-inset-bottom, 0px));
    width: 100%;
    transform: none;
    border-left: 0;
    border-right: 0;
    border-bottom: 0;
  }
  .recruit-head { height: 28px; padding: 0 8px; }
  .recruit-head > div:first-child { gap: 6px; }
  .recruit-head .panel-tag { font-size: 6px; }
  #deploy-name { font-size: 7px; }
  #queue-note { display: none; }
  .recruit-cards {
    gap: 3px;
    padding: 4px;
    overflow-x: auto;
    scrollbar-width: none;
    scroll-snap-type: x mandatory;
  }
  .recruit-cards::-webkit-scrollbar { display: none; }
  .unit-card {
    flex: 0 0 78px;
    min-height: 72px;
    padding: 5px;
    scroll-snap-align: start;
  }
  .unit-card-icon { height: 20px; }
  .unit-card-icon svg { width: 22px; height: 22px; }
  .unit-card-copy b { font-size: 8px; }
  .unit-card-copy small { display: none; }
  .unit-cost { font-size: 7px; }
  .unit-hotkey { display: none; }

  #ability-dock { right: 7px; bottom: 178px; left: auto; }
  .ability-btn { width: 142px; min-height: 38px; padding: 5px 7px; gap: 6px; }
  .ability-icon { width: 23px; height: 23px; font-size: 14px; }
  .ability-copy b { font-size: 8px; }
